import 'package:path_provider/path_provider.dart';
import 'package:path/path.dart' as p;
import '../../features/people/models/person_model.dart';

// This is generated by ObjectBox when you run build_runner
import '../../objectbox.g.dart';

class ObjectBoxService {
  late final Store store;

  ObjectBoxService._(this.store);

  // Initialize the database in the phone's secure local documents folder
  static Future<ObjectBoxService> create() async {
    final docsDir = await getApplicationDocumentsDirectory();
    final store = openStore(directory: p.join(docsDir.path, 'butterfly-db'));
    return ObjectBoxService._(store);
  }

  // --- Quick Helper Methods for Testing ---

  // Add a Person
  int savePerson(Person person) {
    final box = store.box<Person>();
    return box.put(person);
  }

  // int removePerson(Person person) {
  //   final box = store.box<Person>();
  //   return box.remove(person.id);
  // }

  // Get all People
  List<Person> getAllPeople() {
    final box = store.box<Person>();
    return box.getAll();
  }
}